INSERT INTO public._school_family_seed_chunks(slug,payload)
VALUES ('kind-krank-a1', $chunk${"t":"Mein Kind ist krank – A1","d":"Der Lernende kann die Schule telefonisch oder schriftlich informieren, Name und Klasse nennen, Krankheit/Fehlen angeben und nach einer Entschuldigung fragen.","s":[["Guten Morgen. Hier spricht Frau Kovač.","Telefonbeginn"],["Mein Sohn Emir ist krank.","Grund"],["Er ist in der Klasse 2A.","Klasse"],["Er kommt heute nicht in die Schule.","Abmeldung"],["Vielleicht fehlt er auch morgen.","mögliche Dauer"],["Er hat Fieber.","Symptom"],["Er hat auch Husten.","Symptom"],["Danke für die Information.","Antwort"],["Brauchen Sie eine schriftliche Entschuldigung?","Nachfrage"],["Ja, bitte, wenn er wieder kommt.","Anweisung"],["Brauchen Sie ein Attest?","Nachfrage"],["Für einen Tag nicht.","kurze Info"],["Kann ich die Hausaufgaben bekommen?","Nachfrage"],["Ich melde mich morgen noch einmal.","Folge"],["Vielen Dank. Auf Wiederhören.","Telefonabschluss"]],"v":[["krank","—","nicht gesund","Mein Kind ist krank."],["das Fieber","—","erhöhte Temperatur","Er hat Fieber."],["der Husten","—","Husten","Er hat Husten."],["die Schule","die Schulen","Schule","Er kommt heute nicht in die Schule."],["die Klasse","die Klassen","Klasse","Er ist in der Klasse 2A."],["das Sekretariat","die Sekretariate","Schulverwaltung","Ich rufe im Sekretariat an."],["die Krankmeldung","die Krankmeldungen","Info über Krankheit","Ich mache eine Krankmeldung."],["die Entschuldigung","die Entschuldigungen","schriftliche Erklärung","Brauchen Sie eine Entschuldigung?"],["das Attest","die Atteste","ärztliche Bestätigung","Brauchen Sie ein Attest?"],["die Hausaufgabe","die Hausaufgaben","Aufgaben","Kann ich die Hausaufgaben bekommen?"],["fehlen","—","nicht da sein","Er fehlt heute."],["kommen","—","ankommen","Er kommt heute nicht."],["anrufen","—","telefonieren","Ich rufe die Schule an."],["melden","—","informieren","Ich melde mein Kind krank."],["brauchen","—","benötigen","Brauchen Sie ein Attest?"],["bekommen","—","erhalten","Kann ich die Aufgaben bekommen?"],["heute","—","aktueller Tag","Heute bleibt er zu Hause."],["morgen","—","nächster Tag","Vielleicht fehlt er morgen."],["wieder","—","erneut/zurück","Wenn er wieder kommt."],["zu Hause","—","daheim","Mein Kind bleibt zu Hause."],["mein Sohn","—","männliches Kind","Mein Sohn ist krank."],["meine Tochter","—","weibliches Kind","Meine Tochter ist krank."],["Auf Wiederhören","—","Telefonabschluss","Vielen Dank. Auf Wiederhören."],["Hier spricht …","—","Telefonformel","Hier spricht Frau Kovač."],["nicht in die Schule kommen","—","fehlen","Er kommt heute nicht in die Schule."]],"p":["1. Wo ist das kranke Kind? Das Kind ist zu Hause.","2. Wo ruft die Mutter an? Sie ruft im Sekretariat an.","3. Wo liegt das Thermometer? Das Thermometer liegt auf dem Tisch.","4. Wo sind die Hausaufgaben? Die Hausaufgaben sind im Schulportal.","5. Wo gibt das Kind die Entschuldigung ab? Bei der Lehrerin.","6. Wo ist das Attest? Das Attest ist in der Schultasche."],"dgs":[[1,"Mutter","Guten Morgen. Hier spricht Frau Kovač.","Schule anrufen"],[1,"Sekretariat","Guten Morgen.","Schule anrufen"],[1,"Mutter","Mein Sohn Emir ist krank. Er kommt heute nicht in die Schule.","Schule anrufen"],[1,"Sekretariat","In welcher Klasse ist er?","Schule anrufen"],[1,"Mutter","In der Klasse 2A.","Schule anrufen"],[1,"Sekretariat","Danke für die Information.","Schule anrufen"],[2,"Mutter","Brauchen Sie eine schriftliche Entschuldigung?","Entschuldigung und Aufgaben"],[2,"Sekretariat","Ja, bitte.","Entschuldigung und Aufgaben"],[2,"Mutter","Brauchen Sie auch ein Attest?","Entschuldigung und Aufgaben"],[2,"Sekretariat","Für einen Tag nicht.","Entschuldigung und Aufgaben"],[2,"Mutter","Kann ich die Hausaufgaben bekommen?","Entschuldigung und Aufgaben"],[2,"Sekretariat","Ja. Die Lehrerin schickt sie Ihnen.","Entschuldigung und Aufgaben"]],"gn":[["sein/haben bei Krankheit","Diese Struktur wird direkt in der konkreten Alltagssituation geübt.","Guten Morgen. Hier spricht Frau Kovač. · Mein Sohn Emir ist krank. · Er ist in der Klasse 2A."],["Negation nicht","Mit „nicht“ verneint man Verben, Adjektive oder ganze Aussagen.","Mein Kind kommt heute nicht. · Es versteht die Aufgabe nicht. · Das ist nicht richtig."],["Possessiv mein/meine","Possessivformen wie mein/meine und sein/seine zeigen Zugehörigkeit. Pronomen vermeiden Wiederholungen.","Mein Kind ist krank. · Sein Heft liegt hier. · Ich gebe es ab."],["W-Fragen welche/in welcher","W-Fragen beginnen mit einem Fragewort. Danach folgt in der Regel das Verb.","Brauchen Sie eine schriftliche Entschuldigung? · Brauchen Sie ein Attest? · Kann ich die Hausaufgaben bekommen?"],["Modalverb können","Modalverben wie können, müssen, sollen und dürfen stehen konjugiert; der zweite Infinitiv steht am Satzende.","Was muss ich mitbringen? · Können Sie mir helfen? · Was soll mein Kind machen?"],["Trennbares Verb anrufen","Trennbare Verben teilen sich im Hauptsatz: abholen → Ich hole mein Kind ab.","Ich hole mein Kind um 15 Uhr ab. · Bitte füllen Sie das Formular aus. · Ich rufe die Schule an."],["Zeit heute/morgen","Für Uhrzeiten nutzt man meist „um“, für Wochentage/Datum „am“. „bis“ markiert eine Frist.","Er kommt heute nicht in die Schule. · Vielleicht fehlt er auch morgen. · Ich melde mich morgen noch einmal."]],"q":[["practice","Wer beginnt das Gespräch?","Mutter","Sekretariat","Niemand"],["practice","Welche Aussage kommt im Dialog wirklich vor?","Mein Sohn Emir ist krank. Er kommt heute nicht in die Schule.","Brauchen Sie auch ein Attest?","Ich bestelle eine Pizza."],["practice","Welche Aussage gehört zu diesem Dialog?","Brauchen Sie auch ein Attest?","Mein Sohn Emir ist krank. Er kommt heute nicht in die Schule.","Der Zug fährt um sieben Uhr."],["practice","Welche Antwort folgt logisch?","Für einen Tag nicht.","Guten Morgen. Hier spricht Frau Kovač.","Ich möchte eine Jacke kaufen."],["grammar","Welche Aussage passt sprachlich zu diesem Thema?","Guten Morgen. Hier spricht Frau Kovač.","Ich bestelle eine Pizza.","Der Zug fährt nach Wien."],["grammar","Welche Aussage gehört ebenfalls in diese Situation?","Mein Sohn Emir ist krank.","Ich kaufe Benzin.","Der Kellner bringt die Rechnung."],["grammar","Welche Form ist ein vollständiger Satz?","Er ist in der Klasse 2A.","Nur Stichwort","Ohne Verb"],["grammar","Was hilft auf A1 besonders?","kurze klare Sätze","lange komplizierte Nebensätze","Fachjargon"],["grammar","Welches Wort verneint die Aussage?","nicht","bitte","heute"],["grammar","Welche Form ist richtig?","Mein Kind kommt heute nicht.","Mein Kind nicht kommt heute.","Nicht mein Kind heute kommt."],["grammar","Welche Aussage zeigt ein Problem?","Es versteht die Aufgabe nicht.","Alles ist klar.","Danke."],["grammar","Was ist das Gegenteil von „Es versteht die Aufgabe.“?","Es versteht die Aufgabe nicht.","Es nicht die Aufgabe.","Nein Aufgabe."],["grammar","Welche Form zeigt Zugehörigkeit zur sprechenden Person?","mein/meine","der/die","wo/wann"],["grammar","Welche Form passt zu „Kind“?","mein Kind","meine Kind","meinen Kind"],["grammar","Welche Form passt zu „Tochter“?","meine Tochter","mein Tochter","meinen Tochter"],["grammar","Welche Aussage ist korrekt?","Mein Kind ist krank.","Mein Kind sein krank.","Meine Kind ist krank."],["grammar","Welches Fragewort fragt nach einem Ort?","Wo","Wann","Was"],["grammar","Welches Fragewort fragt nach einer Zeit?","Wann","Wo","Wer"],["grammar","Welches Fragewort fragt nach einer Sache/Information?","Was","Wo","Wie alt"],["grammar","Welche Frage passt am besten zum Thema?","Brauchen Sie eine schriftliche Entschuldigung?","Wie teuer ist ein Auto?","Wo ist das Schwimmbad?"],["grammar","Welche zweite Frage passt ebenfalls?","Brauchen Sie ein Attest?","Welche Farbe hat das Wetter?","Wie groß ist die Bank?"],["grammar","Bei einem Modalverb steht der zweite Infinitiv ...","am Satzende","immer am Anfang","direkt vor dem Subjekt"],["grammar","Welche Form ist richtig?","Was muss ich mitbringen?","Muss ich mitbringen was?","Ich muss was mitbringen muss."],["grammar","We